//회원가입
void signup() {
    if (users_count >= MAX_USERS) {
        printf("더 이상 회원가입을 할 수 없습니다\n");
        return;
    }

    //아이디
    printf("학번(=아이디)를 입력하시오 (예시 : 22411888)\n");
    scanf("%14s", users[users_count].id);

    int id_len = strlen(users[users_count].id);

    if (id_len == 8) {

        for (int i = 0; i < 9; i++) {

            if (isdigit(users[users_count].id)) {

            }

