        return;
    }


    //전화번호
    printf("전화번호를 입력하시오 (- 제외)\n");
    scanf("%14s", users[users_count].num);

    int num_len = strlen(users[users_count].num);

    if (num_len == 11) {

        for (int i = 0; i < 12; i++) {

            if (isdigit(users[users_count].num)) {

            }

