//로그인
void login() {
    while (1) {
        printf("로그인을 시작하겠습니다\n\n");
        printf("-1 입력시 로그인 종료\n");
        printf("아이디(=학번)를 입력하시오\n");
        scanf("%14s", id2);

        if (strcmp(id2, "-1") == 0) {
            return;
        }

        printf("비밀번호를 입력하시오\n");
        scanf("%49s", pass2);

        for (int i = 0; i < users_count; i++) {
            if (strcmp(id2, users[i].id) == 0 && strcmp(pass2, users[i].pass) == 0) {
                printf("로그인 되었습니다\n");
                su = 1; // 로그인 상태를 1로 설정
